class Solution {
public:
    bool isEvenOddTree(TreeNode* root) {
        if (!root) return true;
        queue<TreeNode*> q;
        q.push(root);
        int level = 0;
        while (!q.empty()) {
            int sz = q.size();
            int prev = 0;
            bool first = true;
            bool evenLevel = (level % 2 == 0);
            for (int i = 0; i < sz; i++) {
                TreeNode* node = q.front();
                q.pop();
                int v = node->val;
                if (evenLevel) {
                    if (v % 2 == 0) return false;
                    if (!first && v <= prev) return false;
                } else {
                    if (v % 2 != 0) return false;
                    if (!first && v >= prev) return false;
                }
                prev = v;
                first = false;
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            level++;
        }
        return true;
    }
};
